[FormControlEventHandler(formControlStr(NDXPIMCore, IsCatalogItem), FormControlEventType::Modified)]
public static void IsCatalogItem_OnModified(FormControl sender, FormControlEventArgs e)
{
    FormDataSource fds = sender.formRun().dataSource(formDataSourceStr(NDXPimCore, InventTable));
    fds.executeQuery();

}

[FormDataSourceEventHandler(formDataSourceStr(NDXPIMCore, InventTable), FormDataSourceEventType::QueryExecuting)]
public static void InventTable_OnQueryExecuting(FormDataSource sender, FormDataSourceEventArgs e)
{
    QueryBuildRange qbr;
    QueryBuildDataSource qbds = sender.query().dataSourceTable(tableNum(InventTable));
    FormCheckBoxControl fchkbc;

    qbr = SysQuery::findOrCreateRange(qbds, fieldNum(InventTable, KCS_IsCatalogItem));
    fchkbc = sender.formRun().design().controlName("IsCatalogItem");

    if(fchkbc.checked())
    {
        qbr.value(queryValue(NoYes::Yes));
    }
    else
    {
        qbr.value(SysQuery::valueUnlimited());
    }
}
